def test_r1_no_namespace():
    import funcy
    public_names = [name for name in dir(funcy) if not name.startswith('_')]
    assert 'namespace' not in public_names
    # Also ensure that SkipMemory is still present
    assert 'SkipMemory' in public_names

def test_r1_python2_refuses_import(monkeypatch):
    # Simulate Python 2 environment
    monkeypatch.setattr('sys.version_info', (2, 7, 0, 'final', 0))
    # Clear any cached imports of funcy
    import importlib
    import funcy
    # Remove funcy from sys.modules so we can reload with patched version_info
    for mod in list(sys.modules.keys()):
        if mod.startswith('funcy'):
            del sys.modules[mod]
    with pytest.raises((ImportError, RuntimeError)):
        importlib.import_module('funcy')
