def test_r2_lzip_strict_equal_lengths():
    from funcy import lzip
    result = lzip([1,2,3], ['a','b','c'], strict=True)
    assert result == [(1,'a'), (2,'b'), (3,'c')]

def test_r2_lzip_strict_unequal_raises():
    from funcy import lzip
    with pytest.raises(ValueError):
        lzip([1,2], ['a','b','c'], strict=True)

def test_r2_lzip_strict_default_false():
    from funcy import lzip
    # Default strict=False should behave like normal zip
    result = lzip([1,2], ['a','b','c'])
    assert result == [(1,'a'), (2,'b')]

def test_r2_pairwise_unaffected():
    from funcy import pairwise
    # pairwise should still work as before, ignoring strict argument
    result = pairwise([1,2,3])
    assert result == [(1,2), (2,3)]
