def test_r3_get_in_unchanged():
    from funcy import get_in
    # get_in still raises KeyError for missing nested keys? Actually get_in returns default.
    # But the spec says unchanged behaviour: get_in with default returns default.
    # Check that it still works same as before.
    d = {'a': 1}
    assert get_in(d, ['a']) == 1
    assert get_in(d, ['b'], 'default') == 'default'

def test_r3_set_in_unchanged():
    from funcy import set_in
    d = {}
    result = set_in(d, ['a', 'b'], 1)
    assert result == {'a': {'b': 1}}
    # Original unchanged
    assert d == {}
