      "code": "import pytest

def test_r4_arggetter_positional_only():
    from funcy import arggetter
    # Define a function with positional-only argument (Python 3.8+)
    def func(a, b, /):
        pass
    getter = arggetter(func)
    assert getter('a', (1,2), {}) == 1
    assert getter('b', (1,2), {}) == 2
    with pytest.raises(TypeError):
        getter('c', (1,2), {})

def test_r4_arggetter_keyword_only():
    from funcy import arggetter
    def func(*, x, y):
        pass
    getter = arggetter(func)
    assert getter('x', (), {'x': 10}) == 10
    assert getter('y', (), {'y': 20}) == 20
    with pytest.raises(TypeError):
        getter('z', (), {})

def test_r4_has_1pos_and_kwonly_true():
    from funcy import has_1pos_and_kwonly
    def func(a, /, *, b):
        pass
    assert has_1pos_and_kwonly(func) is True

def test_r4_has_1pos_and_kwonly_false():
    from funcy import has_1pos_and_kwonly
    def func(a, b, /):
        pass
    assert has_1pos_and_kwonly(func) is False
    def func2(a, *, b):
        pass
    assert has_1pos_and_kwonly(func2) is False
    def func3(a, b):
        pass
    assert has_1pos_and_kwonly(func3) is False
