def test_r5_autocurry_positional_only():
    from funcy import autocurry
    def func(a, b, /):
        return a + b
    curried = autocurry(func)
    # Curry with both positional arguments
    assert curried(1, 2) == 3
    # Partial application
    assert curried(1)(2) == 3

def test_r5_autocurry_keyword_only():
    from funcy import autocurry
    def func(*, x, y):
        return x + y
    curried = autocurry(func)
    # Must supply keyword arguments
    assert curried(x=1, y=2) == 3
    # Partial application
    assert curried(x=1)(y=2) == 3

def test_r5_rcurry_positional_only():
    from funcy import rcurry
    def func(a, b, /):
        return a - b
    curried = rcurry(func)
    # rcurry applies arguments from the right
    assert curried(1)(2) == -1  # Equivalent to func(2,1)
    assert curried(1,2) == -1

def test_r5_rcurry_keyword_only():
    from funcy import rcurry
    def func(*, x, y):
        return x * y
    curried = rcurry(func)
    # rcurry with keyword-only: probably same as autocurry? Need to behave as expected.
    # Test that it works.
    assert curried(x=2, y=3) == 6
    assert curried(x=2)(y=3) == 6

def test_r5_get_spec_modern_args():
    from funcy import get_spec
    def func(a, b, /, c, d, *, e, f):
        pass
    spec = get_spec(func)
    # spec should have correct max_n, names, req_n, etc.
    # a,b are positional-only, c,d positional-or-keyword, e,f keyword-only
    # Defaults: none, all required
    assert spec.max_n == 6
    assert spec.names == {'a','b','c','d','e','f'}
    assert spec.req_n == 6
    assert spec.req_names == {'a','b','c','d','e','f'}
    assert spec.kw is False  # no **kwargs

def test_r5_get_spec_with_defaults():
    from funcy import get_spec
    def func(a, /, b=0, *, c=1):
        pass
    spec = get_spec(func)
    assert spec.max_n == 3
    assert spec.names == {'a','b','c'}
    assert spec.req_n == 1  # only a is required
    assert spec.req_names == {'a'}
    assert spec.kw is False
